components.snippet:
const rain = UIAbsorbDrops.mount(canvasEl, {
  catcherWidth: 180,
  fallSpeed: 2,
});

rain.spawn(6);
rain.caughtColor();
rain.destroy();

const hoard = UIAcornHoard.mount(canvasEl, {
  count: 14,
  pose: 'smile',
  name: 'Peanut',
});

hoard.set({ count: 21 });
if (hoard.overflowing) { /* say the number in text too */ }

// Or just the arrangement, for any stacked-object count:
const plan = UIAcornHoard.layout(9, { size: 3 });

container.innerHTML = UIBarChart.render(
  [{ label: 'Mon', value: 42 }, { label: 'Tue', value: 58 }],
  { caption: 'Signups by day' }
);

container.innerHTML = UIBlobShape.render({ seed: 7, points: 6, wobble: 0.22 });

// Or take just the path, e.g. for a clip-path:
const d = UIBlobShape.path({ seed: 7 });

const chart = UICanvasChart.mount(canvasEl, {
  type: 'line',
  data: [
    { label: 'Mon', value: 42 },
    { label: 'Tue', value: 58 },
  ],
  color: 'var(--accent)',
});

chart.update(newData);
chart.setType('bar');

const balls = UIClickToSplit.mount(canvasEl, {
  count: 40,
  gravity: 0.4,
  restitution: 0.82,
});

balls.reset();
balls.destroy();

const companion = UICompanionPerch.mount(pageEl, {
  key: location.pathname,   // same key, same perch — no hopping on re-render
  hostSelector: '[data-perch], .card',
  count: 1,
});

companion.update(location.pathname);  // route changed
companion.destroy();

container.innerHTML = UIDonutChart.render(
  [{ label: 'Direct', value: 42 }, { label: 'Search', value: 28 }],
  { size: 180, thickness: 26, centerLabel: '70' }
);

container.innerHTML = UIDuotoneFilter.wrap(
  '<image href="/photo.jpg" width="260" height="170"/>',
  { shadow: '#14532d', highlight: '#e8f5ea' }
);

const field = UIFlowField.mount(canvasEl, {
  particles: 900,
  scale: 9,
  seed: 11,
});

field.destroy();

container.innerHTML = UIGlowFilter.wrap(
  '<circle cx="60" cy="60" r="30" stroke="#4ade80" fill="none"/>',
  { strength: 4, layers: 2 }
);

const goo = UIGooeyBlobs.mount(blobContainer, { blur: 10 });
// …later
goo.destroy();

container.innerHTML =
  UIHeatmapGrid.render(dailyCounts, { columns: 26 }) +
  UIHeatmapGrid.legend();

const grid = UIHitGrid.mount(canvasEl, {
  cell: 40,
  gap: 10,
  onHover: (c) => console.log(c && c.col, c && c.row),
});

grid.destroy();

UIIcons.svg('cube', { size: 20, class: 'icon' })
// -> returns an <svg> string, ready to insert

// for many repeats, mount the sprite once:
UIIcons.mountSprite();
UIIcons.use('cube', { size: 20 })

const board = UILedMatrix.mount(canvasEl, {
  text: 'NOW BOARDING · GATE 12',
  rows: 9,
});

if (board.overflowing) { /* the full string must also exist as text */ }

container.innerHTML = UILiquidFillText.render('STORAGE', {
  value: 0.42,          // 0..1 — this is the data, not decoration
  fill: 'var(--accent)',
});

const panel = UILiquidGlass.mount(cardEl, { blur: 12, distortion: 14 });
// …later
panel.destroy();

// container must be position:relative — the overlay is absolutely positioned.
container.insertAdjacentHTML(
  'beforeend',
  UINoiseGrain.overlay({ baseFrequency: 0.8, opacity: 0.22 })
);

const field = UIParticleField.mount(canvasEl, {
  count: 70,
  linkDist: 110,
  color: 'var(--accent)',
});

field.destroy();

const drawing = UIPathDraw.mount(container, {
  d: 'M40 100 L 120 165 L 262 30',
  duration: 1600,
  loop: false,
});

drawing.replay();
drawing.destroy();

const hatch = UIPatternHatch.make({ kind: 'diagonal', size: 8 });
svg.innerHTML =
  '<defs>' + hatch.defs + '</defs>' +
  '<rect width="100" height="60" fill="' + hatch.fill + '"/>';

const sprite = UIPixelSprite.mount(canvasEl, {
  pose: 'smile',
  scale: 4,
  animate: true,           // idle blink; stops under prefers-reduced-motion
  name: 'Peanut',          // becomes the aria-label
});

sprite.set({ pose: 'worry', mood: 'worried' });

// Or compose a variant yourself — every patch returns a new map:
const chubby = UIPixelSprite.chubify(UIPixelSprite.POSES.joy);

container.innerHTML = UIProgressRing.render({
  value: 62,
  size: 120,
  label: 'Upload progress',
});

const dots = UIProximityDots.mount(canvasEl, {
  count: 220,
  range: 80,
  maxRadius: 22,
  color: 'var(--accent)',
});

dots.destroy();

container.innerHTML = UIRadialGauge.render({
  value: 0.62,
  sweep: 270,
  label: 'Disk usage',
});

const card = UIScratchOff.mount(containerEl, {
  text: 'YOU WIN',
  threshold: 0.55,
  onComplete: () => console.log('revealed'),
});

card.reveal();

container.innerHTML = UISkeletonShimmer.render({
  lines: 3,
  avatar: true,
  label: 'Loading comments',
});

container.innerHTML = UISparkline.render(
  [12, 15, 11, 18, 22, 19, 27],
  { width: 120, height: 32, fill: true, label: 'Signups, rising 12 to 27' }
);

UISpirograph.draw(canvasEl, { R: 120, r: 47, d: 70, color: 'var(--accent)' });

// Or take the points and render them however you like:
const pts = UISpirograph.points({ R: 96, r: 35, d: 84 });

container.innerHTML = UISquiggleWobble.wrap(
  '<circle cx="100" cy="100" r="60" fill="none" stroke="currentColor" stroke-width="3"/>',
  { scale: 18, speed: 1.2 }
);

const grid = UIThreeInstancedGrid.mount(containerEl, {
  side: 16,        // 16 x 16 = 256 instances, one draw call
  spacing: 0.34,
});

grid.destroy();

const cloud = UIThreePoints.mount(containerEl, {
  count: 6000,
  size: 0.022,
  color: 0x2f9e4f,
});

cloud.destroy();

const scene = UIThreeScene.mount(containerEl, {
  geometry: 'icosahedron',
  color: 0x2f9e4f,
});

scene.setPaused(true);
scene.destroy();

const plane = UIThreeShaderPlane.mount(containerEl, {
  fragment: myGlslString,   // omit to use the built-in noise shader
  scale: 3,
});

plane.uniforms.uScale.value = 6;
plane.destroy();

const globe = UIThreeWireframeGlobe.mount(containerEl, {
  points: [{ lat: 37.57, lon: 126.98 }, { lat: 51.51, lon: -0.13 }],
});

// Just the conversion, if that is all you need:
const v = UIThreeWireframeGlobe.latLonToVector3(THREE, 37.57, 126.98, 1.5);

const glitch = UIVhsGlitch.mount(canvasEl, {
  paint: (ctx, w, h) => { /* draw your scene */ },
  split: 4,
});

// Or apply once to whatever is already painted:
UIVhsGlitch.apply(canvasEl, { split: 6, bands: 8 });

container.innerHTML = UIWaveDivider.render({
  amplitude: 18,
  cycles: 2,
  fill: 'var(--surface-alt)',
});
